{"t":"say","text":"I'll add disaster recovery with a cross-region standby database and automated backups."}
{"t":"req","text":"Disaster recovery: system must stay up on failures"}
{"t":"plan","products":["dts","cloud-backup"]}
{"t":"group","id":"dr","kind":"region","label":"Tokyo (ap-northeast-1)","parent":null}
{"t":"node","id":"db-dr","product":"rds","label":"DR Appointments DB","group":"dr","zones":["a","b"],"why":"Standby replica for failover if Seoul region fails."}
